1936	                    const value = field.value.trim();
1937	
1938	                    if (!value) {
1939	                        const label = field.labels?.[0]?.textContent?.split('*')[0].trim() || 'This field';
1940	                        showError(field, `${label} is required`);
1941	                        return false;
1942	                    }
1943	
1944	                    if (!field.checkValidity()) {
1945	                        const validator = fieldValidators[field.id] || fieldValidators[field.type];
1946	                        const customMessage = validator ? validator(field.value) : null;
1947	                        const message = customMessage || 'Please enter a valid value';
1948	                        showError(field, message);
1949	                        return false;
1950	                    }
1951	
1952	                    clearError(field);
1953	                    return true;
1954	                };
1955	
1956	                const messageField = document.getElementById('message');
1957	                const messageCounter = document.getElementById('message-counter');
1958	
1959	                const updateMessageCounter = () => {
1960	                    if (messageCounter) {
1961	                        const length = messageField.value.length;
1962	                        const remaining = 1000 - length;
1963	                        const percentage = Math.round((length / 1000) * 100);
1964	                        messageCounter.textContent = `${length} / 1000 characters (${percentage}%)${remaining < 100 && remaining > 0 ? ` - ${remaining} remaining` : ''}`;
1965	                        if (remaining < 100) {
1966	                            messageCounter.style.color = remaining < 50 ? 'var(--error-color)' : 'var(--primary-color)';
1967	                        } else {
1968	                            messageCounter.style.color = 'var(--text-color)';
1969	                        }
1970	                    }
1971	                };
1972	
1973	                if (messageField && messageCounter) {
1974	                    updateMessageCounter();
1975	                    messageField.addEventListener('input', updateMessageCounter);
1976	                }
1977	
1978	                const debouncedValidate = debounce((field) => validateField(field), 300);
1979	
1980	                const inputs = contactForm.querySelectorAll('input, textarea');
1981	                inputs.forEach(input => {
1982	                    input.addEventListener('change', saveFormDraft);
1983	                    input.addEventListener('blur', () => validateField(input));
1984	                    input.addEventListener('input', () => {
1985	                        if (input.getAttribute('aria-invalid') === 'true') {
1986	                            debouncedValidate(input);
1987	                        }
1988	                    });
1989	                });
1990	
1991	                let isSubmitting = false;
1992	
1993	                contactForm.addEventListener('submit', function(e) {
1994	                    e.preventDefault();
1995	
1996	                    if (isSubmitting) return;
1997	
1998	                    let isValid = true;
1999	                    const feedback = document.getElementById('form-feedback');
2000	                    feedback.className = 'form-feedback';
2001	                    feedback.textContent = '';
2002	
2003	                    inputs.forEach(input => {
2004	                        if (!validateField(input)) isValid = false;
2005	                    });
2006	
2007	                    if (!isValid) {
2008	                        feedback.className = 'form-feedback error';
2009	                        feedback.textContent = 'Please correct the errors above and try again.';
2010	                        feedback.setAttribute('role', 'alert');
2011	                        feedback.setAttribute('aria-live', 'assertive');
2012	                        const firstError = contactForm.querySelector('[aria-invalid="true"]');
2013	                        if (firstError && firstError.focus) {
2014	                            firstError.focus();
2015	                        }
2016	                        return;
2017	                    }
2018	
2019	                    const submitBtn = document.getElementById('submit-btn');
2020	                    isSubmitting = true;
2021	                    submitBtn.disabled = true;
2022	                    submitBtn.classList.add('loading');
2023	                    const originalHTML = submitBtn.innerHTML;
2024	                    const originalAriaLabel = submitBtn.getAttribute('aria-label');
2025	                    submitBtn.innerHTML = '<span class="spinner" aria-hidden="true"></span>Sending...';
2026	                    submitBtn.setAttribute('aria-label', 'Sending message, please wait');
2027	                    submitBtn.setAttribute('aria-busy', 'true');
2028	
2029	                    const startTime = Date.now();
2030	                    const minLoadingDuration = 500;
2031	
2032	                    const formData = new FormData(contactForm);
2033	                    const endpoint = contactForm.getAttribute('data-endpoint') || '/contact';
2034	                    const controller = new AbortController();
2035	                    const timeoutId = setTimeout(() => controller.abort(), 10000);
2036	
2037	                    fetch(endpoint, {
2038	                        method: 'POST',
2039	                        body: formData,
2040	                        signal: controller.signal
2041	                    })
2042	                    .then(response => {
2043	                        if (!response.ok) {
2044	                            if (response.status === 429) {
2045	                                throw new Error('Too many requests. Please wait a moment and try again.');
2046	                            } else if (response.status >= 500) {
2047	                                throw new Error('Server is temporarily unavailable. Please try again later.');
2048	                            } else if (response.status >= 400) {
2049	                                throw new Error(`Request error (${response.status}). Please check your input and try again.`);
2050	                            }
2051	                            throw new Error(`Server error: ${response.status}`);
2052	                        }
2053	                        return response;
2054	                    })
2055	                    .then(() => {
2056	                        feedback.className = 'form-feedback success';
2057	                        feedback.textContent = '✓ Thank you for your message! We will be in touch soon.';
2058	                        feedback.setAttribute('role', 'status');
2059	                        feedback.setAttribute('aria-live', 'polite');
2060	                        contactForm.reset();
2061	                        try {
2062	                            localStorage.removeItem(FORM_STORAGE_KEY);
2063	                        } catch (e) {
2064	                            console.debug('Could not clear form draft');
2065	                        }
2066	                        inputs.forEach(input => {
2067	                            clearError(input);
2068	                            input.setAttribute('aria-invalid', 'false');
2069	                        });
2070	                        updateMessageCounter();
2071	                        setTimeout(() => feedback.scrollIntoView({ behavior: 'smooth', block: 'center' }), 100);
2072	                    })
2073	                    .catch(error => {
2074	                        feedback.className = 'form-feedback error';
2075	                        feedback.setAttribute('role', 'alert');
2076	                        feedback.setAttribute('aria-live', 'assertive');
2077	                        if (error.name === 'AbortError') {
2078	                            feedback.textContent = 'Request timed out. Please check your connection and try again.';
2079	                        } else if (error instanceof TypeError) {
2080	                            feedback.textContent = 'Connection failed. Please check your internet connection and try again.';
2081	                        } else if (error.message) {
2082	                            feedback.textContent = error.message;
2083	                        } else {
2084	                            feedback.textContent = 'Something went wrong. Please try again in a moment.';
2085	                            console.error('Form submission error:', error);
2086	                        }
2087	                    })
2088	                    .finally(() => {
2089	                        clearTimeout(timeoutId);
2090	                        const elapsedTime = Date.now() - startTime;
2091	                        const remainingDelay = Math.max(0, minLoadingDuration - elapsedTime);
2092	
2093	                        setTimeout(() => {
2094	                            isSubmitting = false;
2095	                            submitBtn.disabled = false;
2096	                            submitBtn.classList.remove('loading');
2097	                            submitBtn.innerHTML = originalHTML;
2098	                            submitBtn.removeAttribute('aria-busy');
2099	                            if (originalAriaLabel) {
2100	                                submitBtn.setAttribute('aria-label', originalAriaLabel);
2101	                            }
2102	                            requestAnimationFrame(() => {
2103	                                try {
2104	                                    feedback.scrollIntoView({ behavior: 'smooth', block: 'center' });
2105	                                    if (feedback.textContent) {
2106	                                        feedback.setAttribute('tabindex', '-1');
2107	                                        feedback.focus({ preventScroll: true });
2108	                                        feedback.removeAttribute('tabindex');
2109	                                        if (feedback.classList.contains('success')) {
2110	                                            submitBtn.focus();
2111	                                        }
2112	                                    }
2113	                                } catch (e) {
2114	                                    console.error('Error focusing feedback:', e);
2115	                                }
2116	                            });
2117	                        }, remainingDelay);
2118	                    });
2119	                });
2120	            }
2121	        }
2122	    </script>
2123	</body>
2124	</html>
